package mlmgt

import (
	"context"
	"encoding/hex"

	"gitee.com/kwbasedb/kwbase/pkg/security"
	"gitee.com/kwbasedb/kwbase/pkg/sql/sqlbase"
	"gitee.com/kwbasedb/kwbase/pkg/sql/sqlutil"
)

const (
	// TSLLMName model name
	TSLLMName = "tsllm"
	// kwdbml/fvt/testdata/tsllm/ts_forecasting_py310/trained_model/transformers_4.40/model.zip
	modelHexStr = "504b0304140000000800000021000000000002000000000000000f0000006d6f64656c2f6d6f64656c2e7478740300504b01021403140000000800000021000000000002000000000000000f0000000000000000000000ff01000000006d6f64656c2f6d6f64656c2e747874504b050600000000010001003d0000002f0000000000"
	// kwdbml/fvt/testdata/tsllm/ts_forecasting_py310/dataprep.zip
	//dataPrepHexStr = ""
)

// ImportTSLLM import internal model
func ImportTSLLM(ctx context.Context, ie sqlutil.InternalExecutor) error {
	rows, err := ie.QueryEx(
		ctx,
		"select-tsllm",
		nil,
		sqlbase.InternalExecutorSessionDataOverride{User: security.RootUser},
		`select * from kwdbml.show_model($1)`,
		"public."+TSLLMName,
	)
	if err != nil {
		return err
	}

	if len(rows) > 0 {
		return nil
	}

	modelBytes, err := hex.DecodeString(modelHexStr)
	if err != nil {
		return err
	}

	//dataPrepBytes, err := hex.DecodeString(dataPrepHexStr)
	if err != nil {
		return err
	}

	if _, err := ie.ExecEx(
		ctx,
		"import tsllm",
		nil,
		sqlbase.InternalExecutorSessionDataOverride{User: security.RootUser},
		"select kwdbml.import_model($1,$2,$3,$4,$5,$6,$7,$8,$9)",
		"public."+TSLLMName,
		`[Internal model] features format (one of the following): 
		1. array of "{timestamp},{value}";
		2. array of {value}.
		{value} should can be converted to float`,
		"regression",
		"transformers_4.40",
		"python_3.10",
		`[
			{
				"name": "time_value",
				"type": "array"
			},
			{
				"name": "time_value1",
				"type": "array"
			},
			{
				"name": "time_value2",
				"type": "array"
			}
    	]`,
		`[
			{
				"name": "t",
				"type": "float"
			}
		]`,
		modelBytes,
		nil,
	); err != nil {
		return err
	}

	return nil
}
